 let text=$('#anchor-text'),update=()=>{$('#anchor-count').textContent=[...text.value].length;local.put('drafts',draftId,{text:text.value}).catch(()=>{})};text.oninput=update;update();$('#anchor-form').onsubmit=async e=>{e.preventDefault();let body=old?{text:text.value.trim(),expectedVersion:old.version,visibility:'private'}:{journeyId:s.journey.id,topicId:n.topicId,contentId:n.contentIds[0],text:text.value.trim(),visibility:'private',localOffset:{x:2,y:0,z:3}};try{let d=await api.mutate('/anchors'+(old?'/'+old.id:''),old?'PATCH':'POST',body);if(d.pending){toast('想法已保存在本机待同步队列，尚未确认服务器保存。');setSave('锚点待同步')}else{await local.del('drafts',draftId);await refreshPrivate();toast('想法已保存，只属于你。')}closePanel()}catch(e){$('#anchor-error').innerHTML=`<div class="notice error" style="margin-top:18px">${esc(e.message)} 草稿仍在本机。${e.status===409?'请关闭编辑器后重新打开，比较最新记录。':''}</div>`}}
