async function synthesisPanel(){await refreshPrivate();let materials=[...s.selected].map(id=>s.bag.find(b=>b.id===id)).filter(Boolean);if(materials.length<2)return openPanel('synthesis','思维合成台','把不同地方带回的微光，放在同一张桌上。',empty('带回两份收获，再来试试','从知识行囊选中 2–4 份正文或摘录。话题词本身不是证据。')+`<div class="button-row" style="justify-content:center">${button('bag','打开知识行囊','btn')}</div>`,{size:'narrow'});
 if(materials.some(m=>m.targetType==='topic'||!m.text))return toast('请移除没有正文或摘录的话题词，再选择有效证据。',true);
 openPanel('synthesis','在不同的收获之间','先看清材料来自哪里，再决定想建立什么联系。',`<div class="synthesis-materials">${materials.map(materialCard).join('')}</div><div class="divider"></div><form id="synthesis-form"><label class="field-label" for="synthesis-question">你想借这组材料理解什么？（可选）</label><textarea id="synthesis-question" rows="3" maxlength="200" placeholder="它们之间共同的问题是什么？哪些差异值得保留？"></textarea><div class="form-group" style="margin-top:18px"><label class="field-label" for="synthesis-mode">创作方式</label><select id="synthesis-mode"><option value="manual">手工建立洞察 · 不调用模型</option><option value="ai" ${s.session?.features.aiSynthesis?'':'disabled'}>知乎直答 AI 辅助 · 需要可用服务端密钥</option></select></div><div class="notice">手工模式只整理材料，不会把固定文字冒充实时 AI。AI 模式仅在收到通过证据校验的有效结果后展示；保存前可编辑。</div><button class="btn" type="submit">准备洞察草稿 ${icon('arrow',17)}</button></form>`,{size:'wide'});
 $('#synthesis-form').onsubmit=async e=>{e.preventDefault();let body={bagItemIds:materials.map(m=>m.id),question:$('#synthesis-question').value,mode:$('#synthesis-mode').value};try{let d=await task('/syntheses',body,'synthesis');await insightEditor(d.synthesisId)}catch(e){if(e.message!=='任务已取消。')openPanel('synthesis-failed','洞察草稿未完成','你的材料组合仍保留，可改为手工写下联系。',`<div class="notice error">${esc(e.message)}</div>${button('synthesis','回到选材','btn')}`,{size:'narrow'})}}
}
function materialCard(m){return `<article class="material"><small>${esc(kindLabel(m.kind))} · ${esc(m.sourceLabel)} · ${m.dataMode==='demo'?'演示':'真实来源'}</small><strong>${esc(m.title)}</strong><p>${esc(short(m.text,320))}</p><small>${esc(m.authorName)}${m.sourceUrl?` · <a href="${esc(m.sourceUrl)}" target="_blank" rel="noopener noreferrer">原始来源 ↗</a>`:''}</small></article>`}
async function insightEditor(id){let d=await api.call('/syntheses/'+id),r=d.result;if(d.status==='saved')return insightView(id);let draftId=api.owner+':insight:'+id,localDraft=await local.get('drafts',draftId);if(localDraft?.value)r={...r,...localDraft.value};openPanel('insight-editor',d.generator==='user'?'写下你看见的联系':'AI 洞察草稿 · 请核对与编辑',d.generator==='user'?'手工创作，不含伪装的 AI 输出。':'AI 输出并非原作者观点。请核对来源和适用条件。',`<form id="insight-form"><div class="form-grid"><div class="form-group full"><label class="field-label" for="insight-title">标题</label><input id="insight-title" class="input" name="title" maxlength="100" required value="${esc(r.title)}"></div><div class="form-group full"><label class="field-label" for="insight-core">核心洞察</label><textarea id="insight-core" name="coreInsight" maxlength="2000" required rows="4" placeholder="结合材料，写下你自己的理解…">${esc(r.coreInsight)}</textarea></div><div class="form-group"><label class="field-label" for="insight-connection">联系如何成立？</label><textarea id="insight-connection" name="connection" maxlength="2000">${esc(r.connection)}</textarea></div><div class="form-group"><label class="field-label" for="insight-uncertainty">差异与不确定性</label><textarea id="insight-uncertainty" name="uncertainty" maxlength="1000">${esc(r.uncertainty)}</textarea></div><div class="form-group full"><label class="field-label" for="insight-questions">接下来想探索的问题（最多三行）</label><textarea id="insight-questions" name="questions" rows="2" maxlength="600">${esc((r.questions||[]).join('\n'))}</textarea></div></div><div class="section-title">本次实际使用的材料</div><div class="synthesis-materials">${d.materials.map(materialCard).join('')}</div><div class="button-row" style="margin-top:24px"><button class="btn" type="submit">保存洞察，带回家园</button></div><p class="help">结果保存后，进入日志和同一份收藏库。来源引用随结果一起保留。</p></form>`,{size:'wide'});
 let form=$('#insight-form');const value=()=>({title:form.elements.title.value,coreInsight:form.elements.coreInsight.value,connection:form.elements.connection.value,uncertainty:form.elements.uncertainty.value,questions:form.elements.questions.value.split('\n').map(x=>x.trim()).filter(Boolean).slice(0,3),personalNote:''});form.oninput=()=>local.put('drafts',draftId,value()).catch(()=>{});form.onsubmit=async e=>{e.preventDefault();try{let result=await api.mutate('/syntheses/'+id+'/save','POST',value());if(result.pending){toast('洞察已在本机待同步，尚未确认保存。');closePanel()}else{await local.del('drafts',draftId);await refreshPrivate();sound();toast('洞察已保存。旅途中的微光，有了新的联系。');await insightView(id)}}catch(e){toast(e.message,true)}}
}
async function insightView(id){let d=await api.call('/insights/'+id),r=d.result;openPanel('insight-view',r.title,`${d.generator==='user'?'个人手工洞察':'AI 辅助洞察，用户已核对保存'} · ${date(d.savedAt||d.createdAt)}`,`<p class="callout-quote">${esc(r.coreInsight)}</p>${r.connection?`<div class="section-title">联系说明</div><p>${esc(r.connection)}</p>`:''}${r.uncertainty?`<div class="notice">差异与不确定性：${esc(r.uncertainty)}</div>`:''}${r.questions?.length?`<div class="section-title">下一段旅程的问题</div>${r.questions.map(q=>`<p>${esc(q)}</p>`).join('')}`:''}<div class="section-title">沿着来源，回到证据</div><div class="synthesis-materials">${d.materials.map(materialCard).join('')}</div>`,{size:'wide',footer:`<small>源材料属于原作者，洞察属于你的个人记录。</small>${button('delete-insight','删除这份洞察','btn small secondary',`data-id="${id}"`)}`})}
async function journalPanel(tab='journeys'){let [js,insights]=await Promise.all([fetchAll('/journeys'),api.call('/insights')]);openPanel('journal','漫行者日志','一条小径，一次停留。你走过的路，都有迹可循。',`<div class="tabs">${button('journal','探索旅程','tab '+(tab==='journeys'?'active':''))}${button('insights-tab','保存的洞察','tab '+(tab==='insights'?'active':''))}${button('anchors','私人锚点','tab')}${button('outbox','待同步与草稿','tab')}</div>${tab==='journeys'?(js.length?js.map((j,i)=>`<article class="journal-card"><div class="number">${String(js.length-i).padStart(2,'0')}</div><div><h3>${esc(j.seedText)}</h3><p>${date(j.startedAt)} · ${j.status==='active'?'进行中':j.status==='paused'?'已暂停':'已归档'} · ${j.stats.topics} 个已访问话题 · ${j.stats.collections} 次收获 · ${j.stats.anchors} 个锚点</p><div style="margin-top:8px">${modeBadge(j.dataMode,true)}</div></div><div class="actions">${j.status!=='completed'?button('resume-journey','继续','btn small',`data-id="${j.id}"`):''}${button('journey-map','星图','btn small secondary',`data-id="${j.id}"`)}${button('remove-journey','删除','mini-btn',`data-id="${j.id}"`)}</div></article>`).join(''):empty('你的第一条小径，尚未开始','回到小屋，推开大门，让一个问题成为起点。')):(insights.items.length?insights.items.map(d=>`<article class="anchor-card"><div class="context">${d.generator==='user'?'手工洞察':'AI 辅助洞察'} · ${date(d.savedAt||d.createdAt)}</div><h3>${esc(d.result.title)}</h3><p>${esc(short(d.result.coreInsight,140))}</p>${button('insight-view','打开洞察','btn small secondary',`data-id="${d.id}"`)}</article>`).join(''):empty('收获之间，还可以有新的联系','选择至少两份材料，带到思维合成台。'))}`,{size:'wide'})}
function mapSvg(nodes,edges,highlight=null){if(!nodes.length)return '';let xmin=Math.min(...nodes.map(n=>n.position.x))-15,xmax=Math.max(...nodes.map(n=>n.position.x))+15,zmin=Math.min(...nodes.map(n=>n.position.z))-15,zmax=Math.max(...nodes.map(n=>n.position.z))+15,scale=Math.min(600/(xmax-xmin),300/(zmax-zmin)),p=n=>[50+(n.position.x-xmin)*scale,30+(n.position.z-zmin)*scale];let colors=['#bdd6a0','#dcc086','#89bdad','#b9b2a0'];return `<svg viewBox="0 0 700 370" role="img" aria-label="按实际话题访问绘制的私人星图">${edges.map(e=>{let a=nodes.find(n=>n.topicId===e.topics?.[0]||n.id===e.source),b=nodes.find(n=>n.topicId===e.topics?.[1]||n.id===e.target);if(!a||!b)return '';let [x1,y1]=p(a),[x2,y2]=p(b);return `<path d="M${x1} ${y1}L${x2} ${y2}" stroke="#b3c092" stroke-width="${1+Math.min(4,e.count||0)}" stroke-opacity="${e.count?.length?'.8':'.35'}" fill="none"/>`}).join('')}${nodes.map((n,i)=>{let [x,y]=p(n),r=6+Math.min(n.visits||0,5)*1.7,active=highlight===n.topicId,opacity=(n.visits||active)?.65+Math.min(n.dwellSeconds||0,600)/600*.35:.38;return `<g class="map-node" tabindex="0" role="button" aria-label="${esc(n.title)}" data-map-node="${n.id}"><circle cx="${x}" cy="${y}" r="${r+8}" fill="${colors[i%4]}" fill-opacity="${active?.35:.08}"/><circle cx="${x}" cy="${y}" r="${r}" fill="${colors[i%4]}" opacity="${opacity}" stroke="${active?'#fff4cd':'#b3cd9d'}" stroke-width="${active?2:.5}"/><text x="${x}" y="${y+25}" text-anchor="middle" fill="#e3e9d5" font-size="11" font-family="serif">${esc(n.title)}</text></g>`}).join('')}</svg>`}
async function mapPanel(jid=s.journey?.id){if(!jid)return journalPanel();await flushEvents();let data=await api.call('/journeys/'+jid+'/canvas'),nodes=data.nodes,edges=data.edges.length?data.edges:s.world?.edges||[],steps=data.steps.filter(x=>x.type==='topic_entered');openPanel('canvas','我的旅途星图',data.journey.seedText,`<div class="map-container"><div class="map-wrap" id="map-wrap">${mapSvg(nodes,edges)}<div class="map-legend">色彩：区域类别 · 大小：访问次数 · 亮度：有效停留（最多 600 秒）<br>线宽：往返次数 · 灰暗节点：已生成，尚未访问 · 连线不是事实推断</div></div><aside class="map-info" id="map-info"><div class="eyebrow">YOUR OWN TRAIL</div><h3>一路走来，<br>你留下了什么？</h3><p>${data.journey.stats.topics} 个实际访问话题<br>${data.bag.length} 份仍保留的收获<br>${data.anchors.length} 个私人想法</p><p>点击一个节点，回到它关联的内容。这里记录的是语义访问，不是逐帧动作录像。</p></aside></div><label class="slider-label" for="map-time">访问时间线<input type="range" id="map-time" min="0" max="${steps.length}" value="0"><span id="map-time-label">全部</span></label>`,{size:'wide',footer:`<small>${modeBadge(data.journey.dataMode,true)} · ${date(data.journey.startedAt)}</small><div class="button-row">${data.journey.status!=='completed'?button('resume-journey','回到这段旅程','btn small',`data-id="${jid}"`):''}${button('journal','回到日志','btn small secondary')}</div>`});
 function bind(){ $$('[data-map-node]').forEach(el=>{let view=()=>{let n=nodes.find(n=>n.id===el.dataset.mapNode),bag=data.bag.filter(b=>b.topicId===n.topicId),anchors=data.anchors.filter(a=>a.topicId===n.topicId);$('#map-info').innerHTML=`<div class="eyebrow">${esc(n.biome)}</div><h3>${esc(n.title)}</h3><p>访问 ${n.visits} 次 · 有效停留 ${Math.round(n.dwellSeconds)} 秒<br>${bag.length} 份收获 · ${anchors.length} 个想法</p>${bag.map(b=>`<p>✧ ${esc(b.title)}</p>`).join('')}${anchors.map(a=>`<p>「${esc(short(a.text,90))}」</p>`).join('')}${s.journey?.id===jid&&s.page==='world'?button('topic','打开这个话题','btn small secondary',`data-id="${n.id}"`):''}`};el.onclick=view;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();view()}}})}bind();$('#map-time').oninput=()=>{let step=steps[Number($('#map-time').value)-1];$('#map-time-label').textContent=step?`${step.seq} · ${date(step.occurredAt)}`:'全部';let legend=$('.map-legend').outerHTML;$('#map-wrap').innerHTML=mapSvg(nodes,edges,step?.topicId)+legend;bind()}
}
function pausePanel(){engine?.pause();if(!s.journey)return home({skipPause:true});openPanel('pause','让脚步休息一下','保存并回家后，可以继续这段旅程；归档后，历史只读。',`<div class="notice">${esc(s.world.seedText)}<br>已确认的收藏和锚点不会因退出漫游而丢失。</div><div class="button-row">${button('pause-home','保存并回家','btn')}${button('archive','结束并归档','btn secondary')}${button('close','留在这里','text-btn')}</div>${s.readonly?`<div class="notice warn" style="margin-top:20px">当前标签页没有写入控制权。${button('takeover','重新载入 / 显式接管','text-btn')}</div>`:''}`,{size:'narrow'})}
async function pauseJourney(){try{engine?.pause();await flushEvents();await saveCheckpoint();let cp=cpNow(),j=await api.call('/journeys/'+s.journey.id+'/pause','POST',{expectedVersion:s.journey.version,checkpoint:cp});s.journey=j;await home({skipPause:true});toast('旅程已保存。欢迎回家。')}catch(e){openPanel('save-failed','暂时未确认保存','本机检查点草稿已保留，不会显示“云端已保存”。',`<div class="notice error">${esc(e.message)}</div><div class="button-row">${button('pause-home','重试保存','btn')}${button('local-home','保留本机草稿后回家','btn secondary')}</div>`,{size:'narrow'})}}
async function archiveJourney(){if(!await confirmDialog('结束并归档这段旅程？','已确认收藏与锚点保留；这段探索的事件与检查点不再修改。','归档旅程'))return;try{await flushEvents();await saveCheckpoint();let id=s.journey.id;s.journey=await api.call('/journeys/'+id+'/complete','POST',{expectedVersion:s.journey.version});await home({skipPause:true});await mapPanel(id)}catch(e){toast(e.message,true)}}
async function confirmDialog(title,description,label='确认'){return new Promise(resolve=>{openPanel('confirm',title,description,`<div class="button-row"><button class="btn danger" id="confirm-yes">${esc(label)}</button><button class="btn secondary" id="confirm-no">取消</button></div>`,{size:'narrow'});$('#confirm-yes').onclick=()=>{closePanel();resolve(true)};$('#confirm-no').onclick=()=>{closePanel();resolve(false)};$('#overlay-root [data-action="close"]').onclick=e=>{e.stopPropagation();closePanel();resolve(false)}})}
function phonePanel(){openPanel('phone','同频电话亭','有一天，你会遇见沿着相似问题走来的旅人。',`<div class="empty"><div class="phone-illustration" aria-hidden="true"></div><h3 style="margin-top:25px">电话还没有响起。</h3><p>同频匹配、公开锚点与聊天尚未开放。<br>这里没有虚构的在线人数，也没有随机生成的匹配率。</p><div class="notice">你的旅程、想法与收藏默认私人。未来仅在你主动公开且允许匹配后，才会使用公开轨迹寻找同路人。</div>${button('journal','先看看自己的旅途','btn secondary')}</div>`,{size:'narrow'})}
function settingsPanel(){openPanel('settings','把漫游调成你的节奏','设置保存在当前浏览器；关闭面板后生效。',`

 <div class="settings-row"><label for="setting-quality">画质<small>主要调整渲染像素比；不影响内容与存档。</small></label><select id="setting-quality">${['low','medium','high'].map((x,i)=>`<option value="${x}" ${s.settings.quality===x?'selected':''}>${['低','中','高'][i]}</option>`).join('')}</select></div>
 <div class="settings-row"><label for="setting-auto">自动降低画质</label><input id="setting-auto" type="checkbox" ${s.settings.autoQuality?'checked':''}></div>
 <div class="settings-row"><label for="setting-motion">减少动态效果<small>关闭角色呼吸摆动；导航改为静态分段线。</small></label><input id="setting-motion" type="checkbox" ${s.settings.reduceMotion?'checked':''}></div>
 <div class="settings-row"><label for="setting-sensitivity">鼠标灵敏度</label><input id="setting-sensitivity" type="range" min="0.3" max="2" step="0.1" value="${s.settings.sensitivity}"></div>
 <div class="settings-row"><label for="setting-invert">反转鼠标 Y 轴</label><input id="setting-invert" type="checkbox" ${s.settings.invertY?'checked':''}></div>
 <div class="settings-row"><label for="setting-sound">轻音效<small>只在用户操作后播放；没有自动播放的背景音乐。</small></label><input id="setting-sound" type="checkbox" ${s.settings.sound?'checked':''}></div>
 <div class="settings-row"><label for="setting-volume">音效音量</label><input id="setting-volume" type="range" min="0" max="0.5" step="0.01" value="${s.settings.volume}"></div>
 <div class="settings-row"><label for="setting-text">界面文字基准</label><select id="setting-text">${[16,18,20].map(x=>`<option ${s.settings.textSize===x?'selected':''}>${x}</option>`).join('')}</select></div>
 <p class="help" style="margin-top:20px">访客记录依赖当前浏览器身份；连续 30 天未使用后可能清理。服务端需要持久磁盘。清理 Cookie 后无法自动证明原身份。</p>
 <div class="button-row">${button('clear-data','清除我的全部应用数据','btn small secondary')}${button('outbox','查看本机待同步','text-btn')}</div>`,{size:'narrow',footer:button('apply-settings','应用设置','btn')})}
async function commitSettings(){s.settings={...s.settings,quality:$('#setting-quality').value,autoQuality:$('#setting-auto').checked,reduceMotion:$('#setting-motion').checked,sensitivity:+$('#setting-sensitivity').value,invertY:$('#setting-invert').checked,sound:$('#setting-sound').checked,volume:+$('#setting-volume').value,textSize:+$('#setting-text').value};applySettings();closePanel();render();toast('已保存体验设置。')}
async function retryRenderer(){
 if(engine){if(!await engine.retryScene())return}
 else{await createEngine();if(!engine||engine.status==='error')return;if(s.world&&await engine.setScene(s.page,s.world,s.field,recoveryCheckpoint||s.journey?.checkpoint)===false)return;engine.setContents([...s.contentMap.values()])}
 recoveryCheckpoint=null;render();
}

function creditsPanel(){openPanel('credits','漫知录 · 关于这片森林','WANDERWISE LAND / 1.0.0',`<div class="credits"><p>以问题为起点，以空间探索为入口，以精神家园为沉淀场所。带走观点，也留下自己的思考。</p><h3>这个运行版包含什么？</h3><p>Three.js / ES Modules 前端、FastAPI / SQLite 后端；Blender 制作的书屋、KayKit 免费 CC0 家具、系统字体生成的中文标签、原创演示文章。应用不依赖外部 CDN，也不包含任何开发者密钥。</p><h3>来源与边界</h3><p>自带路线明确标记为演示。真实内容仅通过服务端知乎适配器取得，并标明来源与获取时间。搜索摘要不是全文。场域使用有来源段落的规则导览，不冒充模型理解。手工洞察不会伪称 AI 生成。</p><h3>资产说明</h3><p>书屋建筑与定制陈设由本项目制作，选用 Kay Lousberg 的 Furniture Bits 1.0 免费 CC0 家具；许可与文件哈希随包提供。Tiny Treats Lovely Living Room 付费包尚未取得。无字体二进制文件随包分发。第三方 Python 依赖按各自许可证使用。</p><h3>隐私与社区</h3><p>所有旅程、锚点和洞察默认私人。同频、OAuth 与聊天未开放。不会自动向知乎发布内容。无第三方统计脚本，无访客画像推断。</p><h3>验收状态</h3><p>完整外部验收需要在可访问官方接口的网络中核验、配置持久化 HTTPS 部署，并执行真实设备测试。详细结果和技术栈偏差见随包 TEST_REPORT 与 REQUIREMENTS_TRACEABILITY 文档。</p></div>`,{size:'narrow'})}
async function outboxPanel(){let entries=(await local.all('outbox')),drafts=(await local.all('drafts')).filter(x=>x.id.startsWith(api.owner+':'));openPanel('outbox','本机待同步与草稿','待同步不是保存成功。不同访客身份的旧操作不会自动迁移。',`<div class="notice">${entries.filter(e=>e.value.owner===api.owner).length} 项当前身份待同步 · ${drafts.length} 项当前身份草稿。检查点和未上传事件不会跨标签页自动覆盖服务端版本。</div>${entries.length?entries.map(e=>`<div class="anchor-card"><div class="context">${esc(e.value.method)} ${esc(e.value.path)} · ${date(e.value.queuedAt)}</div><p>${e.value.owner===api.owner?'属于当前访客':'旧访客身份，禁止自动迁移'}${e.value.error?' · '+esc(e.value.error):''}</p>${button('discard-pending','丢弃这项待同步','mini-btn',`data-id="${esc(e.id)}"`)}</div>`).join(''):empty('没有尚未确认的业务写入','收藏和私人锚点以服务端成功响应为准。')}${drafts.filter(d=>d.id.includes(':anchor:')||d.id.includes(':insight:')).map(d=>`<div class="anchor-card"><div class="context">本机文本草稿</div><p>${esc(d.value.text||d.value.coreInsight||'尚未填写文本')}</p><p class="help">可复制草稿后，在对应语境重新打开编辑器。</p></div>`).join('')}<div class="button-row">${button('sync-now','尝试同步当前身份操作','btn')}${button('journal','回到日志','text-btn')}</div>`)}
async function synchronize(){if(!s.session)return;await api.flush((result,v,e)=>{if(e)toast('有待同步操作需要处理：'+e.message,true)});await refreshPrivate();if(s.modal==='outbox')await outboxPanel();else if(!s.modal)render()}
let audio=null;
function sound(){if(!s.settings.sound)return;try{audio=audio||new (window.AudioContext||window.webkitAudioContext)();audio.resume();let osc=audio.createOscillator(),gain=audio.createGain();osc.type='sine';osc.frequency.setValueAtTime(620,audio.currentTime);osc.frequency.exponentialRampToValueAtTime(930,audio.currentTime+.15);gain.gain.setValueAtTime(.001,audio.currentTime);gain.gain.exponentialRampToValueAtTime(Math.max(.002,s.settings.volume),audio.currentTime+.025);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.4);osc.connect(gain);gain.connect(audio.destination);osc.start();osc.stop(audio.currentTime+.41);osc.onended=()=>{osc.disconnect();gain.disconnect()}}catch{}}
async function perform(action,id,el){switch(action){
 case 'brand':case 'enter-home':return home();case 'close':return closePanel();case 'credits':return creditsPanel();case 'settings':return settingsPanel();case 'apply-settings':return commitSettings();case 'retry-scene':return retryRenderer();case 'retry-low-quality':s.settings.quality='low';s.settings.autoQuality=false;applySettings();return retryRenderer();case 'roam':if(s.readonly)return toast('当前只读，请从日志重新载入或显式接管。',true);return engine?.resume();case 'seed':return seedsPanel();case 'preset':{let p=s.presets.find(p=>p.id===id);return startWorld({seedMode:p.dataMode==='demo'?'demo':'preset',presetId:p.id})}case 'random-seed':{let ps=s.presets.filter(p=>p.dataMode==='demo'),p=ps[Math.floor(Math.random()*ps.length)];return startWorld({seedMode:'demo',presetId:p.id})}case 'knowledge-catalog':return catalogPanel();case 'knowledge':return startWorld({seedMode:'knowledge',presetId:id});case 'cancel-job':return cancelProgress();case 'bag':return bagPanel();case 'bag-filter':return bagPanel(id);case 'bag-edit':return editBag(id);
 case 'bag-source':{let b=s.bag.find(b=>b.id===id);if(b.targetType==='insight')return insightView(b.targetId);if(b.contentId)return readContent(b.contentId,b.excerptId);return toast('这是一个话题词，不是正文证据。')}
 case 'bag-remove':{let b=s.bag.find(b=>b.id===id),ls=(await api.call('/bag/links')).items.filter(l=>l.sourceBagItemId===id||l.targetBagItemId===id);if(await confirmDialog('从收藏库移除？',`只删除个人收藏关系，不删除原内容。${ls.length} 条手工连线也会删除；已保存洞察保留引用快照。`,'移除收藏')){await api.call('/bag/items/'+id,'DELETE');s.selected.delete(id);return bagPanel()}return bagPanel()}
 case 'collect-content':return collect('content',id);case 'collect-excerpt':return collect('excerpt',id);case 'read-content':return readContent(id);case 'enter-field':return enterField(id);case 'return-world':return returnWorld();case 'topic':return topicPanel(id);case 'expand-node':return expandNode(s.world.nodes.find(n=>n.id===id));case 'track-node':{let n=s.world.nodes.find(n=>n.id===id);closePanel();engine?.cycleNav(n);return updateNav()}case 'cancel-nav':if(engine)engine.navigation.mode=0;return updateNav();case 'anchor':return anchorEditor();case 'anchors':return anchorsPanel();case 'edit-anchor':return anchorEditor(id);
 case 'remove-anchor':if(await confirmDialog('删除这个私人想法？','删除后会从场景与日志同步移除。','删除锚点')){await api.call('/anchors/'+id,'DELETE');await refreshPrivate()}return anchorsPanel();
 case 'synthesis':case 'selected-synthesis':return synthesisPanel();case 'link-materials':return linkMaterials();case 'links-panel':return linksPanel();case 'remove-link':await api.call('/bag/links/'+id,'DELETE');return linksPanel();case 'journal':return journalPanel();case 'insights-tab':return journalPanel('insights');case 'insight-view':return insightView(id);case 'delete-insight':if(await confirmDialog('删除这份洞察？','其对应收藏和手工连线也会移除，源材料仍保留。','删除洞察')){await api.call('/insights/'+id,'DELETE');await refreshPrivate()}return journalPanel('insights');case 'map':return mapPanel();case 'journey-map':return mapPanel(id);case 'resume-journey':return loadJourney(id);case 'takeover':return loadJourney(s.journey.id,true);case 'remove-journey':if(await confirmDialog('删除这段私人旅程？','收藏、私人锚点与已保存洞察保留；仅删除旅程事件、检查点及其关联。','删除旅程')){await api.call('/journeys/'+id,'DELETE');if(s.journey?.id===id)await home({skipPause:true})}return journalPanel();case 'pause':return pausePanel();case 'pause-home':return pauseJourney();case 'local-home':return home({skipPause:true});case 'archive':return archiveJourney();case 'phone':return phonePanel();case 'outbox':return outboxPanel();case 'sync-now':return synchronize();case 'discard-pending':if(await confirmDialog('丢弃这项本机待同步操作？','未送达服务端的修改将被放弃。','丢弃'))await local.del('outbox',id);return outboxPanel();
 case 'clear-data':if(await confirmDialog('清除我的全部应用数据？','此访客的旅程、收藏、锚点、洞察和本机草稿将删除。其他访客与公共内容缓存不受影响。','永久清除')){await api.call('/me/data','DELETE',{confirm:'DELETE_MY_DATA'});for(let st of ['outbox','drafts','cache'])await local.clear(st);location.href='/'}return;
 }}
document.addEventListener('click',e=>{let el=e.target.closest('[data-action]');if(!el)return;e.preventDefault();Promise.resolve(perform(el.dataset.action,el.dataset.id,el)).catch(e=>toast(e.message,true))});
document.addEventListener('keydown',e=>{if(!s.modal)return;if(e.key==='Escape'){e.preventDefault();closePanel();return}if(e.key==='Tab'){let candidates=$$('#overlay-root button:not([disabled]),#overlay-root a,#overlay-root input:not([disabled]),#overlay-root textarea,#overlay-root select').filter(el=>el.offsetParent!==null),first=candidates[0],last=candidates.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
function engineAction(action,t){if(s.modal)return;let near=getContext();if(t?.node&&s.page==='world')contextNode=t.node;switch(action){case 'b':return bagPanel();case 'r':return anchorEditor();case 't':return anchorsPanel('context');case 'v':{let n=t?.node||near;engine.cycleNav(n);if(n)queueEvent('navigation_started',n.topicId);return updateNav()}case 'read':if(!t)return;if(t.type==='facility'&&({door:'seed',cabinet:'bag',synthesis:'synthesis',journal:'journal',phone:'phone'})[t.id]===t.action)return perform(t.action);if(t.type==='node'){if(dist(engine.player,t.position)>4)return toast('再靠近一点，才能阅读或收集。');return topicPanel(t.node.id)}return readContent(t.content.id,t.excerpt.id);case 'e':if(!t)return toast('先靠近一份可收集的金句。');if(dist(engine.player,t.position)>4)return toast('距离较远，无法收集。');return t.type==='excerpt'?collect('excerpt',t.excerpt.id):t.type==='node'?collect('topic',t.node.topicId):null;case 'f':if(t?.type==='excerpt')return enterField(t.content.id);return toast('靠近一份具有正文的金句，才能进入场域。')}}
function onSceneState(status,error=''){
 s.sceneState=status;s.sceneError=error;let el=$('#scene-load');if(!el){el=document.createElement('div');el.id='scene-load';document.body.append(el)}
 el.classList.toggle('hidden',status==='ready');
 el.innerHTML=status==='loading'?'<div class="scene-loading-card"><span class="eyebrow">林间灯火 · 知识书屋</span><h3>正在打开书屋</h3><p>准备家具、光线与安全落点…</p></div>':status==='error'?`<div class="scene-loading-card"><h3>小屋暂时没有准备好</h3><p>${esc(error)}</p><div class="button-row">${button('retry-scene','重新加载','btn')}${button('retry-low-quality','以低画质重试','btn secondary')}</div></div>`:'';
}
async function createEngine(){
 if(engine)return;if(engineCreation){await engineCreation;return createEngine()}
 if(needsCanvasReset){const canvas=$('#world');canvas.replaceWith(canvas.cloneNode(false));needsCanvasReset=false}
 engineCreation=(async()=>{
  try{const {Engine}=await import(rendererPreference==='legacy'?'./engine/legacy/engine.js':'./engine/engine.js');engine=new Engine($('#world'),{sceneState:onSceneState,notice:toast,action:(a,t)=>Promise.resolve(engineAction(a,t)).catch(e=>toast(e.message,true)),escape:()=>{if(s.modal)return;if(s.page!=='landing'&&s.page!=='home')pausePanel()},active:onActive,target:onTarget,near:n=>{if(s.page==='world')contextNode=n},visit:n=>{if(s.page==='world')queueEvent('topic_entered',n.topicId,{dwellSeconds:2},n.id)},leave:(n,t)=>{if(n&&s.page==='world')queueEvent('topic_left',n.topicId,{dwellSeconds:Math.min(t,120)},n.id)},navigation:updateNav,expand:n=>expandNode(n,true),contextLost:()=>{recoveryCheckpoint=engine?.checkpoint();engine?.dispose();engine=null;needsCanvasReset=true;onSceneState('error','三维画面暂时中断。已保存记录不受影响，请重试。')},metrics:m=>{diagnostics=m;let el=$('#diag');if(el)el.textContent=`3D · ${m.fps} FPS · ${m.drawCalls} DRAWS · ${Math.round(m.triangles/1000)}K TRIANGLES`}});await engine.ready;}catch{engine?.dispose();engine=null;onSceneState('error','暂时无法启动三维画面。请确认浏览器支持 WebGL2 并开启硬件加速，再重试。')}

 })();try{await engineCreation}finally{engineCreation=null}
}
async function init(){
 $('#app').innerHTML='<div class="loading-screen"><img src="/static/assets/mark.svg" alt=""><h2>漫知录</h2><p>正在整理家园与私人存档</p></div>';
 try{
  let session=await api.call('/session/guest','POST',{});api.csrf=session.csrfToken;api.owner=session.user.id;s.session=session;s.presets=(await api.call('/seeds')).items;await refreshPrivate();
  await createEngine();
  if(['127.0.0.1','localhost'].includes(location.hostname)&&new URLSearchParams(location.search).get('qa')==='1'){const {installRenderQA}=await import('./engine/render-qa.js');installRenderQA(()=>engine)}
  applySettings();render();await synchronize();let match=location.pathname.match(/^\/journeys\/([^/]+)/),canvasMatch=location.pathname.match(/^\/canvas\/([^/]+)/);if(match){await loadJourney(match[1]);let ev=await local.get('drafts',api.owner+':events:'+match[1]);eventsBuffer=ev?.value?.events||[]}else if(canvasMatch){s.page='home';render();await mapPanel(canvasMatch[1])}else if(location.pathname==='/home'){s.page='home';render()}else if(location.pathname==='/settings')settingsPanel();else if(location.pathname==='/credits')creditsPanel();
 }catch(e){$('#app').innerHTML=`<div class="loading-screen"><img src="/static/assets/mark.svg" alt=""><h2>家园暂时没有连接成功</h2><p>${esc(e.message)}</p><p>请确认通过启动脚本访问，不要直接双击 index.html。</p><div class="button-row" style="justify-content:center"><button class="btn primary" id="boot-retry">重新连接</button></div></div>`;$('#boot-retry').onclick=()=>location.reload()}
}
window.addEventListener('online',()=>synchronize().catch(()=>toast('网络已恢复，但服务仍不可达。',true)));
window.addEventListener('offline',()=>{engine?.pause();setSave('离线 · 修改待同步');toast('网络离线。已有内容仍可阅读，新增业务写入会明确保留为待同步。')});
window.addEventListener('popstate',()=>{let m=location.pathname.match(/^\/journeys\/([^/]+)/);if(m)loadJourney(m[1]).catch(e=>toast(e.message,true));else home().catch(e=>toast(e.message,true))});
setInterval(()=>{if(s.journey?.status==='active'&&!document.hidden&&!s.busy&&!s.readonly)saveCheckpoint().catch(()=>{})},10000);
setInterval(()=>{if(!document.hidden)flushEvents()},5000);
setInterval(()=>{if(s.session&&!document.hidden)api.call('/session/guest','POST',{}).then(session=>{if(session.user.id!==api.owner){engine?.pause();s.readonly=true;toast('访客身份已变化。旧草稿保留，请刷新后核对身份。',true);return}s.session=session;api.csrf=session.csrfToken}).catch(()=>{})},20*60000);
// Read-only diagnostics for manual QA. No credentials, private text or mutation bypasses exposed.
window.wanderwiseDiagnostics=()=>({page:s.page,renderer:engine?(engine.renderer.webgl?'three-webgl2':'native-webgl2'):'unavailable',sceneState:engine?.status||s.sceneState||'loading',sceneKind:engine?.kind,sceneStage:engine?.scene?.stage,eye:engine?.eye?.slice(),target:engine?.target?.id,active:engine?.active,facilities:engine?.kind==='home'?engine.scene?.targets?.map(t=>({id:t.id,position:{...t.position}})):undefined,assetBytes:engine?.scene?.assetBytes,position:engine?{...engine.player}:null,camera:engine?{...engine.camera}:null,metrics:{...diagnostics,...engine?.renderer?.metrics},pending:s.pending,worldVersion:s.world?.version,nodeCount:s.world?.nodes.length,modal:s.modal});
init();
